import ast
import math

def analyze_function_signature(source):
    tree = ast.parse(source.strip())
    node = tree.body[0]
    args = node.args
    total = len(args.posonlyargs) + len(args.args) + len(args.kwonlyargs)
    if args.vararg is not None:
        total += 1
    if args.kwarg is not None:
        total += 1
    lambda_count = 0
    for d in args.defaults:
        if isinstance(d, ast.Lambda):
            lambda_count += 1
    for d in args.kw_defaults:
        if d is not None and isinstance(d, ast.Lambda):
            lambda_count += 1
    return (node.name, math.sqrt(total), lambda_count)

