def max_weight_substring(x, w):
    n = len(x)
    vals = [w.get(c, 0) for c in x]
    S = [0] * (n + 1)
    for i in range(n):
        S[i + 1] = S[i] + vals[i]
    best_key = None
    bi = bj = 0
    for i in range(n + 1):
        for j in range(i, n + 1):
            key = (-(S[j] - S[i]), i, j - i)
            if best_key is None or key < best_key:
                best_key = key
                bi, bj = i, j
    return x[bi:bj]

