import math
from itertools import permutations

def factorial_sums_of_permutations(numbers):
    if not isinstance(numbers, list):
        raise ValueError('numbers should be a list of integers')
    for x in numbers:
        if isinstance(x, bool) or not isinstance(x, int):
            raise ValueError('numbers should be a list of integers')
        if x < 0:
            raise ValueError('numbers should be non-negative')
    if not numbers:
        return [], []
    perms = list(permutations(numbers))
    sums = [sum(math.factorial(x) for x in p) for p in perms]
    return sums, perms

