import math

def _is_number(s):
    try:
        float(s)
        return True
    except (ValueError, TypeError):
        return False

def _gammainc(a, x):
    if x <= 0 or a <= 0:
        return 0.0
    if x < a + 1.0:
        ap = a
        summ = 1.0 / a
        delt = summ
        for n in range(1, 1000):
            ap += 1
            delt *= x / ap
            summ += delt
            if abs(delt) < abs(summ) * 1e-15:
                break
        return summ * math.exp(-x + a * math.log(x) - math.lgamma(a))
    tiny = 1e-300
    b = x + 1.0 - a
    c = 1.0 / tiny
    d = 1.0 / b
    h = d
    for i in range(1, 1000):
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        delp = d * c
        h *= delp
        if abs(delp - 1.0) < 1e-15:
            break
    q = math.exp(-x + a * math.log(x) - math.lgamma(a)) * h
    return 1.0 - q

def _chi2_sf(x, k):
    if x <= 0:
        return 1.0
    return 1.0 - _gammainc(k / 2.0, x / 2.0)

def chi_square_independence_p_value(data, col1, col2):
    if not data or all(len(v) == 0 for v in data.values()):
        raise ValueError('empty')
    if col1 not in data or col2 not in data:
        raise ValueError('missing column')
    v1 = list(data[col1])
    v2 = list(data[col2])
    if len(v1) == 0 or len(v2) == 0:
        raise ValueError('empty')
    if all(_is_number(x) for x in v1) or all(_is_number(x) for x in v2):
        raise ValueError('non-categorical')
    cats1 = list(dict.fromkeys(v1))
    cats2 = list(dict.fromkeys(v2))
    if len(cats1) < 2 or len(cats2) < 2:
        raise ValueError('single category')
    idx1 = {c: i for i, c in enumerate(cats1)}
    idx2 = {c: i for i, c in enumerate(cats2)}
    table = [[0] * len(cats2) for _ in cats1]
    for a, b in zip(v1, v2):
        table[idx1[a]][idx2[b]] += 1
    for row in table:
        for c in row:
            if c < 5:
                raise ValueError('small counts')
    n = sum(sum(r) for r in table)
    rowsums = [sum(r) for r in table]
    colsums = [sum(table[r][c] for r in range(len(cats1))) for c in range(len(cats2))]
    chi = 0.0
    for r in range(len(cats1)):
        for c in range(len(cats2)):
            e = rowsums[r] * colsums[c] / n
            if e > 0:
                chi += (table[r][c] - e) ** 2 / e
    dof = (len(cats1) - 1) * (len(cats2) - 1)
    return float(_chi2_sf(chi, dof))

