        if n == 0:
            return 0.0
        mx = sum(x) / n
        my = sum(y) / n
        num = sum((a - mx) * (b - my) for a, b in zip(x, y))
        dx = sum((a - mx) ** 2 for a in x)
        dy = sum((b - my) ** 2 for b in y)
        if dx == 0 or dy == 0:
            return 0.0
        return num / ((dx ** 0.5) * (dy ** 0.5))

    results = []
    for i in range(n_cols):
        for j in range(i + 1, n_cols):
            xi = [data[r][i] for r in range(n_rows)]
            xj = [data[r][j] for r in range(n_rows)]
