def summarize_values(values):
    values = list(values)
    if not values:
        return {'mean': 0.0, 'median': 0.0, 'mode': 0.0}
    mean = sum(values) / len(values)
    s = sorted(values)
    m = len(s)
    if m % 2 == 1:
        median = s[m // 2]
    else:
        median = (s[m // 2 - 1] + s[m // 2]) / 2
    counts = Counter(values)
    max_freq = max(counts.values())
