        if n is None:
            return v
        return n * 2

    def norm(n):
        if isinstance(n, int):
            return n
        f = float(n)
        if f.is_integer():
            return int(f)
        return f

    if not isinstance(data, dict) or not data:
        return []
    transformed = {}
    for k, v in data.items():
        if isinstance(v, list):
            transformed[k] = [double(e) for e in v]
        else:
            transformed[k] = double(v)
    lengths = {len(v) for v in transformed.values() if isinstance(v, list)}
    if len(lengths) > 1:
        return []
    nrows = lengths.pop() if lengths else 1
    columns = {}
