    core_indices = [i for i in range(n) if core[i]]
    label_map = {}
    cluster_id = 0
    for i in core_indices:
        if i not in label_map:
            stack = [i]
            while stack:
                cur = stack.pop()
                if cur in label_map:
                    continue
                label_map[cur] = cluster_id
                for j in core_indices:
                    if j != cur and j not in label_map and dist(cur, j) <= eps:
                        stack.append(j)
            cluster_id += 1
    labels = [-1] * n
    for i in core_indices:
        labels[i] = label_map[i]
    for p in range(n):
        if core[p]:
