import numpy as np
from scipy.spatial.distance import cdist

def assign_density_clusters(points):
    n = len(points)
    if n == 0:
        return []
    pts = np.array([[float(x) for x in row] for row in points], dtype=float)
    dist = cdist(pts, pts)
    eps = 3.0
    min_samples = 2
    core_mask = (dist <= eps).sum(axis=1) >= min_samples
    core_indices = [i for i in range(n) if core_mask[i]]
    labels = np.full(n, -2, dtype=int)
    next_cluster = 0
    for i in core_indices:
        if labels[i] == -2:
            stack = [i]
            labels[i] = next_cluster
            while stack:
                cur = stack.pop()
                for j in core_indices:
                    if labels[j] == -2 and dist[cur, j] <= eps:
                        labels[j] = next_cluster
                        stack.append(j)
            next_cluster += 1
    for i in range(n):
        if not core_mask[i]:
            assigned = False
            for c in core_indices:
                if dist[i, c] <= eps:
                    labels[i] = labels[c]
                    assigned = True
                    break
            if not assigned:
                labels[i] = -2
    labels[labels == -2] = -1
    return [int(x) for x in labels]

