def compute_tfidf_without_urls(texts):
    n = len(texts)
    url_pattern = re.compile(r'https?://\S+')
    word_pattern = re.compile(r'[A-Za-z0-9_]{2,}')
    cleaned_docs = []
    for doc in texts:
        no_url = url_pattern.sub('', doc)
        cleaned_docs.append([w.lower() for w in word_pattern.findall(no_url)])
    vocab = sorted(set(w for ws in cleaned_docs for w in ws))
    if not vocab:
        return ([], [])
    vocab_index = {w: i for i, w in enumerate(vocab)}
    V = len(vocab)
    tf = [[0] * V for _ in range(n)]
    for i, words in enumerate(cleaned_docs):
        for w in words:
            tf[i][vocab_index[w]] += 1
    df = [sum(1 for i in range(n) if tf[i][j] > 0) for j in range(V)]
    idf = [math.log((1 + n) / (1 + df[j])) + 1 for j in range(V)]
    rows = []
    for i in range(n):
        raw = [tf[i][j] * idf[j] for j in range(V)]
        norm = math.sqrt(sum(x * x for x in raw))
        if norm == 0:
            vec = [0.0] * V
        else:
            vec = [x / norm for x in raw]
        rows.append([round(x, 8) for x in vec])
    return (vocab, rows)

