import re
import numpy as np

def compute_tfidf_without_urls(texts):
    url_re = re.compile(r'https?://\S+')
    word_re = re.compile(r'[a-z0-9_]{2,}')
    tokenized = [word_re.findall(url_re.sub('', d).lower()) for d in texts]
    vocab = sorted(set(w for ws in tokenized for w in ws))
    if not vocab:
        return ([], [])
    idx = {w: i for i, w in enumerate(vocab)}
    N = len(texts)
    V = len(vocab)
    tf = np.zeros((N, V))
    for r, ws in enumerate(tokenized):
        for w in ws:
            tf[r, idx[w]] += 1
    df = np.count_nonzero(tf > 0, axis=0)
    idf = np.log((1 + N) / (1 + df)) + 1
    raw = tf * idf
    norms = np.linalg.norm(raw, axis=1)
    out = np.zeros_like(raw)
    for r in range(N):
        if norms[r] > 0:
            out[r] = raw[r] / norms[r]
    rows = [[round(float(out[r, j]), 8) + 0.0 for j in range(V)] for r in range(N)]
    return (vocab, rows)

