    skew_val = None
    kurt_val = None
    if len(counts_list) >= 2:
        arr = np.array(counts_list, dtype=float)
        if np.var(arr) != 0:
            s = skew(arr, bias=True)
            k = kurtosis(arr, bias=True)
            if not (np.isnan(s) or np.isinf(s)):
                skew_val = float(s)
            if not (np.isnan(k) or np.isinf(k)):
                kurt_val = float(k)
    return (result, skew_val, kurt_val)

