import numpy as np

def standardize_table(columns, rows, substitutions, categorical):
    R = len(rows)
    C = len(columns)
    sub_rows = [[substitutions.get(v, v) for v in row] for row in rows]
    cat_names = set(categorical) if categorical is not None else set()
    cat = [False] * C
    for c in range(C):
        if categorical is not None:
            cat[c] = columns[c] in cat_names
        else:
            allnum = True
            for r in range(R):
                try:
                    float(sub_rows[r][c])
                except ValueError:
                    allnum = False
                    break
            cat[c] = not allnum
    matrix = np.zeros((R, C), dtype=float)
    for c in range(C):
        if cat[c]:
            vals = [sub_rows[r][c] for r in range(R)]
            rank = {v: i for i, v in enumerate(sorted(set(vals)))}
            for r in range(R):
                matrix[r, c] = rank[vals[r]]
        else:
            for r in range(R):
                matrix[r, c] = float(sub_rows[r][c])
    outm = np.full((R, C), np.nan, dtype=float)
    if R > 1:
        for c in range(C):
            col = matrix[:, c]
            std = col.std(ddof=1)
            if std != 0:
                outm[:, c] = (col - col.mean()) / std
    result = []
    for r in range(R):
        row = []
        for c in range(C):
            v = outm[r, c]
            row.append(None if np.isnan(v) else float(v))
        result.append(row)
    return result

