import numpy as np

def zscore_normalize_columns(matrix):
    for row in matrix:
        for v in row:
            if isinstance(v, bool) or not isinstance(v, (int, float, np.number)):
                raise ValueError('non-numeric entry')
    mat = np.array(matrix, dtype=float)
    mean = mat.mean(axis=0)
    std = mat.std(axis=0, ddof=0)
    normalized = np.zeros_like(mat)
    nz = std != 0
    normalized[:, nz] = (mat[:, nz] - mean[nz]) / std[nz]
    normalized[:, ~nz] = 0.0
    return normalized.tolist()

