    s = s.strip()
    formats = ["%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d/%m/%Y", "%m-%d-%Y", "%d-%m-%Y", "%B %d, %Y", "%b %d, %Y", "%d %B %Y", "%B %d %Y", "%Y.%m.%d", "%d.%m.%Y", "%Y%m%d", "%m/%d/%y", "%d/%m/%y"]
