def _gauss_solve(A, b):
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]
    for col in range(n):
        pivot_row = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot_row][col]) < 1e-12:
            continue
        M[col], M[pivot_row] = M[pivot_row], M[col]
        pv = M[col][col]
        for j in range(col, n + 1):
            M[col][j] /= pv
        for r in range(n):
            if r != col:
                f = M[r][col]
                if f != 0:
                    for j in range(col, n + 1):
                        M[r][j] -= f * M[col][j]
    return [M[i][n] for i in range(n)]

def linear_fit_r_squared(target, columns, rows):
    rows = [[float(v) for v in r] for r in rows]
    t = columns.index(target)
    pidx = [i for i in range(len(columns)) if i != t]
    Y = [r[t] for r in rows]
    X = [[1.0] + [r[i] for i in pidx] for r in rows]
    n = len(rows)
    k = len(pidx) + 1
    XtX = [[0.0] * k for _ in range(k)]
    XtY = [0.0] * k
    for xr, yr in zip(X, Y):
        for i in range(k):
            XtY[i] += xr[i] * yr
            for j in range(k):
                XtX[i][j] += xr[i] * xr[j]
    beta = _gauss_solve(XtX, XtY)
    preds = [sum(beta[i] * xr[i] for i in range(k)) for xr in X]
    mean_y = sum(Y) / n if n else 0.0
    ss_res = sum((Y[i] - preds[i]) ** 2 for i in range(n))
    ss_tot = sum((y - mean_y) ** 2 for y in Y)
    if ss_tot < 1e-12:
        return 1.0 if ss_res < 1e-9 else 0.0
    return 1.0 - ss_res / ss_tot

