import numpy as np

def walk_positions(length, steps):
    if length < 0:
        raise ValueError("length must be a non-negative integer")
    steps = list(steps)
    if len(steps) < length:
        steps = steps + [0] * (length - len(steps))
    else:
        steps = steps[:length]
    arr = np.array(steps, dtype=np.int64)
    positions = np.concatenate(([0], np.cumsum(arr))) if length > 0 else np.array([0])
