import pandas as pd

def count_item_combinations(rows):
    sorted_rows = [tuple(sorted(r)) for r in rows]
    if not sorted_rows:
        return {}
    cols = ['a', 'b', 'c', 'd', 'e']
    df = pd.DataFrame(sorted_rows, columns=cols)
    counts = df.groupby(cols).size().reset_index(name='count')
    counts = counts.sort_values(cols)
    result = {}
    for _, row in counts.iterrows():
        result[tuple(str(row[c]) for c in cols)] = int(row['count'])
    return result

