import numpy as np

def log10_values(numbers):
    if not numbers:
        return []
    nums = np.array([int(t) for t in numbers], dtype=np.float64)
    with np.errstate(divide='ignore'):
        logs = np.log10(nums)
    result = []
    for v in logs:
        if np.isneginf(v):
            result.append(None)
        else:
            result.append(float(v))
    return result

