import csv, io, re

def _is_number(s):
    try:
        int(s)
        return True
    except ValueError:
        pass
    try:
        float(s)
        return True
    except ValueError:
        return False

def _decode(s):
    return re.sub(r'\\u([0-9a-fA-F]{4})', lambda m: chr(int(m.group(1), 16)), s)

def decode_unicode_column(csv_text):
    rows = [r for r in csv.reader(io.StringIO(csv_text)) if r]
    if not rows:
        return []
    header = rows[0]
    if 'UnicodeString' not in header:
        raise ValueError('UnicodeString column not found')
    idx = header.index('UnicodeString')
    data = rows[1:]
    for r in data:
        if _is_number(r[idx]):
            raise ValueError('numeric value in UnicodeString column')
    out = [list(header)]
    for r in data:
        nr = list(r)
        nr[idx] = _decode(nr[idx])
        out.append(nr)
    return out

