import csv, io, re
import pandas as pd

def decode_unicode_column(csv_text):
    lines = csv_text.splitlines()
    if not lines:
        return []
    columns = next(csv.reader([lines[0]]))
    if 'UnicodeString' not in columns:
        raise ValueError('UnicodeString column not found')
    df = pd.read_csv(io.StringIO(csv_text), dtype=str, keep_default_na=False)
    if df.empty:
        return [columns]

    def is_number(s):
        s = s.strip()
        if s == '':
            return False
        try:
            float(s)
            return True
        except ValueError:
            return False

    col = df['UnicodeString']
    if col.apply(is_number).any():
        raise ValueError('numeric value in UnicodeString column')

    def decode(s):
        return re.sub(r'\\u([0-9a-fA-F]{4})', lambda m: chr(int(m.group(1), 16)), s)

    df['UnicodeString'] = col.apply(decode)
    return [columns] + [[str(v) for v in r] for r in df.values.tolist()]
